export const request = async (url) => {
  const response = await fetch(url);

  if (response.status >= 500 && response.status < 600) {
    return fetch(url);
  }

  return response;
};

import { readFile } from 'node:fs/promises';

const supportInstructionUrl = new URL(
  '../moldea/agents/customer-support/instruction.md',
  import.meta.url,
);

export const loadSupportInstructions = () => readFile(supportInstructionUrl, 'utf8');

export const runSupportAgent = async (responsesClient, customerMessage) => {
  const instructions = await loadSupportInstructions();

  const firstResponse = await responsesClient.responses.create({
    input: customerMessage,
    instructions,
  });

  return responsesClient.responses.create({
    input: 'The order lookup completed successfully.',
    instructions,
    previous_response_id: firstResponse.id,
  });
};

