import assert from 'node:assert/strict';
import test from 'node:test';

import { loadSupportInstructions, runSupportAgent } from './support-agent.js';

test('passes the canonical instruction to both Responses calls', async () => {
  const requests = [];
  const responsesClient = {
    responses: {
      create: async (request) => {
        requests.push(request);
        return { id: `response-${requests.length}` };
      },
    },
  };

  await runSupportAgent(responsesClient, 'Where is order 123?');

  assert.equal(requests.length, 2);
  assert.equal(requests[0].instructions, requests[1].instructions);
  assert.equal(requests[0].instructions, await loadSupportInstructions());
});

